INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 2, 'theory', 'Quiz: shell, pipelines and scripts');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 0, 'Who expands *.txt into a list of files when you type ls *.txt?', '["The kernel in the execve call", "The ls program itself", "The shell itself, before the program starts: ls gets the ready list", "The standard library when opening the file"]', 2, 'Expansions are the shell''s job. The program receives an array of arguments, and there is no asterisk in it anymore; the kernel takes no part in parsing the line.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 1, 'Which pair of calls is at the heart of starting any program on Linux?', '["fork creates a copy of the process, exec replaces the program in the copy", "open and read", "socket and connect", "mmap and munmap"]', 0, 'The shell calls fork, the child calls exec, and the parent waits with wait. Between fork and exec the shell has time to swap the descriptors.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 2, 'How does cmd > out 2>&1 differ from cmd 2>&1 > out?', '["They do not differ: the order of redirections does not matter", "In the second one both streams go to the file", "In the first one errors are lost", "In the first one both streams end up in the file, in the second one errors stay on the terminal"]', 3, '2>&1 copies where the output points at that moment. If you copy first and redirect the output afterwards, errors stay at the old place.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 3, 'What does the kernel do if the pipe buffer between two programs of a pipeline is full?', '["Throws away old data", "Puts the writing program to sleep until the reading one frees up space", "Grows the buffer without limit", "Terminates the reading program"]', 1, 'A pipe is a kernel buffer of a few tens of kilobytes. Blocking the writer when the buffer is full and the reader when it is empty balances the speeds without storing data on disk.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 4, 'Why do scripts turn on set -o pipefail?', '["So that a failure of any stage makes the whole pipeline fail", "So that the pipeline runs faster", "So that error output goes to a file", "To forbid using empty variables"]', 0, 'Without pipefail, the pipeline''s exit code is the code of the last command, and a failure at the start is easy to miss.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 5, 'What does the notation command 2>&1 do?', '["Copies the command''s output to a file named 1", "Runs the command twice and merges the output", "Sends the standard error stream to wherever standard output currently points", "Passes the command''s result to the next command in the pipeline"]', 2, 'The redirection replaces a descriptor: descriptor 2 now points to the same open file entry as descriptor 1. The order in which redirections are written matters.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 6, 'Why, in cmd1 | cmd2, does the second command not wait for the first to finish?', '["The shell first saves all of the first command''s output into a temporary file", "Both start at the same time and are connected by a pipe: while the buffer has room, the writer works, and the reader takes data as it appears", "The second command itself starts the first one in the background", "The kernel runs them one after another on a single processor"]', 1, 'A pipe is a kernel buffer. If it is empty, the reader sleeps; if it is full, the writer sleeps, so the speed adjusts itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 2, 7, 'What does a program''s exit code of zero mean?', '["The program printed nothing", "The program was interrupted by a signal", "The program ended early without finishing its work", "Success: the shell treats any other value as an error, and this is what if, && and || rely on"]', 3, 'The exit code is the only thing the parent learns about the result. Zero means success, and the shell''s conditional operators check exactly that.');
